window.PORTAL={"day": 14, "title": "Nutrition & Micronutrients", "docTitle": "DAY 14 | NUTRITION & MICRONUTRIENTS", "subtitle": ["DAY 14 — NUTRITION & MICRONUTRIENTS | MCQ DISTRACTOR REWRITE — WORKING EDITION", "REVIEW STATUS: All 81 original MCQs are included. 26 questions have targeted distractor rewrites; 55 retain their original wording. The 26 revised questions require expert revalidation of the new options and explanations. The complete 81-question bank has NOT passed the mandatory three-level review and must not be represented as the final validated examination edition."], "source": "source/Day14_Nutrition_MCQ_Distractor_Rewrite_Working_Edition.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "DAY 14 — NUTRITION &amp; MICRONUTRIENTS | MCQ DISTRACTOR REWRITE — WORKING EDITION"}, {"t": "p", "html": "REVIEW STATUS: All 81 original MCQs are included. 26 questions have targeted distractor rewrites; 55 retain their original wording. The 26 revised questions require expert revalidation of the new options and explanations. The complete 81-question bank has NOT passed the mandatory three-level review and must not be represented as the final validated examination edition."}, {"t": "p", "html": "NEET-SS + ICP Paediatrics  •  12 October 2026  •  Learner-facing standalone study edition"}, {"t": "p", "html": "Scope: Breastfeeding; complementary feeding; nutritional assessment; MAM/SAM; vitamins A/D/B12; iron, zinc and iodine; preventive paediatrics and Indian programme dosing. Prior-topic links are restricted to Days 1–13."}, {"t": "p", "html": "Assessment: 75 base MCQs (7 Basic, 13 Conceptual, 27 Clinical, 20 High-Difficulty, 8 Integrated) + 6 extra notebook retests; 8 separate calculation-drill problems. Extra retests and drill never replace base MCQs."}, {"t": "p", "html": "Source hierarchy: Nelson Textbook of Pediatrics, 22nd ed. for conceptual structure; IAP Presidential Action Plan 2026 and IAP consensus for Indian care; MoHFW/NHM/MoWCD for programme operations; WHO only where explicitly identified as international evidence or comparison."}]}, {"title": "Learning Objectives", "h1": "Learning Objectives", "blocks": [{"t": "list", "ordered": true, "items": ["Interpret WAZ, HAZ, WHZ and MUAC independently and identify edematous SAM even when anthropometry appears reassuring.", "Distinguish SAM/MAM from severe stunting and decide facility versus community care by appetite and complications.", "Sequence SAM stabilization, transition, rehabilitation, discharge and relapse prevention without mixing F-75 and F-100.", "Counsel on human-milk transfer, late-preterm feeding and complementary-food density/diversity/responsive feeding.", "Recall Indian vitamin A, vitamin D, IFA and zinc programme anchors and separate prevention from therapy.", "Interpret iron deficiency versus thalassemia trait, calcipenic versus phosphopenic rickets, and B12 neurological presentations.", "Apply calculations for starter feed, catch-up energy, elemental iron, dextrose and micronutrient dosing.", "Resolve Indian-versus-international guideline conflicts by naming the source and strength of recommendation."]}]}, {"title": "Objective → clinical-case → MCQ coverage map", "h1": "", "blocks": [{"t": "table", "head": ["<strong>Objective cluster</strong>", "<strong>Clinical cases</strong>", "<strong>MCQ emphasis</strong>"], "rows": [["Feeding quality / transfer", "Cases 1–2", "Breastfeeding, late preterm, complementary feeding, food density"], ["Anthropometry / SAM disposition", "Cases 3–4", "MUAC–WHZ discordance, edema, appetite, danger signs"], ["SAM phases / calculations", "Case 5", "F-75, F-100, energy/volume, fluids, anemia"], ["Micronutrients / national programmes", "Cases 6–7", "Vitamin A/D, AMB, zinc, iodine, B12, copper"], ["Cross-system synthesis", "Case 8", "Rickets and iron/B12 differentials; neonatal carry-over"]]}]}]}, {"id": "part-1", "title": "Self-Contained Conceptual and Clinical Notes", "eyebrow": "Part A", "group": "Study Notes", "kind": "notes", "sections": [{"title": "A1. Nutrition assessment: select the right index", "blocks": [{"t": "p", "html": "Mechanistic chain: low intake / malabsorption / recurrent infection → negative energy and micronutrient balance → loss of weight or lean tissue (wasting) and, if sustained, impaired linear growth (stunting) → infection vulnerability and developmental risk → growth-trajectory and anthropometric diagnosis → feeding, medical and community intervention."}, {"t": "table", "head": ["<strong>Index</strong>", "<strong>Interpretation</strong>", "<strong>Exam discriminator</strong>"], "rows": [["Weight-for-age z (WAZ)", "Underweight; combines acute and chronic effects", "Cannot diagnose SAM or distinguish stunting from wasting alone"], ["Length/height-for-age z (HAZ)", "Stunting; &lt;−2 SD, severe &lt;−3 SD", "Chronic linear growth deficit"], ["Weight-for-length/height z (WHZ)", "Wasting; MAM −3 to &lt;−2, SAM &lt;−3", "Acute deficit; can be masked by edema"], ["MUAC (6–59 months)", "SAM &lt;115 mm; MAM 115–&lt;125 mm", "Independent criterion, not averaged with WHZ"], ["Bilateral nutritional pitting edema", "SAM irrespective of WHZ or MUAC", "Fluid retention masks weight loss"]]}, {"t": "p", "html": "WHO child-growth standards are used from birth to five years; IAP Indian growth charts are used for ages five to eighteen/nineteen depending on the metric. The IAP 2026 nutrition assessment chapter emphasizes serial trends, clinical examination, dietary assessment, laboratory context and social determinants. A fall in weight-for-age z-score of approximately ≥1 over time warrants attention even before the absolute z-score crosses −2. [IAP-Assessment, IAP-Infant]"}, {"t": "p", "html": "Growth surveillance sequence: (1) verify age, gestation correction when relevant and measurement technique; (2) plot serial values; (3) determine index-specific abnormalities; (4) review feeding/illness/psychosocial history; (5) examine for edema, micronutrient signs and systemic disease; (6) intervene and document a timed growth reassessment."}]}, {"title": "A2. Breastfeeding and milk-transfer assessment", "blocks": [{"t": "p", "html": "IAP 2026: initiate breastfeeding ideally in the first hour, provide exclusive breast milk for the first six completed months, begin complementary food at six months, and continue breastfeeding to two years or beyond. Colostrum contains concentrated immune factors and is not “poor-quality milk.” Mature human milk contains approximately 67 kcal/100 mL and ~1.1 g protein/100 mL (IAP 2026 table); human milk is low in iron concentration, but bioavailability is relatively high. At six months iron needs outgrow milk-only supply. [IAP-Infant]"}, {"t": "p", "html": "Effective feeding: body aligned and facing mother; wide-open mouth; chin touching breast; lower lip everted; more areola visible above than below; rhythmic swallowing and actual milk transfer. A shallow painful latch can coexist with long feeds and low intake. Evaluate serial weight, urine output, stool pattern, jaundice and feeding observation. IAP 2026 modified LATCH: 0–3 needs professional help; 4–7 some assistance; 8–10 effective feeding (use the specific IAP scoring version named in the question)."}, {"t": "p", "html": "Late preterm (34–36 weeks): immature suck–swallow–breathe coordination can produce deceptively good-looking latch with poor transfer. Risks include hypernatremic dehydration, hypoglycemia and jaundice. Support KMC, 8–12 feeding opportunities/day, observed swallowing, measured transfer where feasible and expressed maternal milk (donor milk if available) when supplementation is medically needed. [IAP-Infant]"}, {"t": "p", "html": "Under-six-month growth failure: the 2025 IAP/Pediatric &amp; Adolescent Nutrition Society recommendation prioritizes mother–infant dyad assessment and skilled lactation support, uses weight-for-age as a practical risk signal, and directs medically complicated infants to facility-based care. Do not transplant MUAC thresholds from 6–59-month children to young infants without the relevant age-specific pathway. [IAP-U6M]"}]}, {"title": "A3. Complementary feeding: quality, quantity and behavior", "blocks": [{"t": "p", "html": "At six completed months, provide thick, nutrient-dense complementary food in addition to breast milk. Typical meal-frequency exam anchors: 6–8 months about 2–3 meals/day; 9–23 months about 3–4 meals/day, with 1–2 nutritious snacks as needed. Increase quantity and texture gradually with developmental readiness; use soft mashed foods progressing toward family foods. For preterm infants, timing is individualized to corrected age, chronological age, nutritional needs and head/trunk/oral-motor readiness; IAP 2026 explicitly notes uncertainty around precise preterm timing. [IAP-Infant, NIN-2024]"}, {"t": "p", "html": "Aim for diverse foods: cereals/roots, pulses/legumes/nuts (age-safe form), dairy, eggs, flesh foods if acceptable, vitamin-A-rich vegetables/fruits and other vegetables/fruits. The 2026 IAP chapter describes a ≥5-of-8 food-group diversity goal and ~0.8–1.0 kcal/g as a useful energy-density anchor for complementary foods. The actual density of home preparations varies; do not treat the illustrative figure as a measured universal value. Add oil/ghee in appropriate amounts, iron-rich foods and vitamin C to enhance non-heme iron absorption. Avoid tea, sugary drinks and screen-assisted force feeding."}, {"t": "p", "html": "Responsive feeding = watch hunger and satiety signals, feed patiently, permit self-feeding when ready, use repeated non-coercive exposure and do not force or distract with screens. In illness continue breast milk and appropriate feeding. A child can meet meal-frequency indicators but fail dietary-diversity and iron-density targets."}]}, {"title": "A4. MAM/SAM: criteria, disposition and management", "blocks": [{"t": "p", "html": "For ages 6–59 months, IAP 2026 SAM: WHZ &lt;−3 and/or MUAC &lt;11.5 cm and/or bilateral nutritional pitting edema. MAM: WHZ −3 to &lt;−2 and/or MUAC 11.5–&lt;12.5 cm, without nutritional edema. The presence of any SAM criterion is sufficient; do not average measures. Evaluate bilateral edema grade: + feet/ankles; ++ lower legs/hands; +++ generalized edema. WHO 2023 recommends inpatient care for +++ edema even with good appetite. [IAP-SAM, WHO-Wasting]"}, {"t": "p", "html": "Indian 2023 CMAM disposition: medical complications or failed appetite test → facility/NRC referral; uncomplicated child with good appetite → supervised community rehabilitation. Appetite test in the MoWCD protocol is performed in a quiet setting with weight-banded test feed, allowing up to an hour; consuming at least three-quarters is a pass. A normal MUAC cannot override nutritional edema; normal vital signs cannot override failed appetite. [MoWCD-CMAM]"}]}, {"title": "Algorithm 1 — acute malnutrition triage (Indian pathway)", "blocks": [{"t": "list", "ordered": true, "items": ["Screen: WHZ, MUAC, bilateral edema; check age and measurement validity.", "If any SAM criterion is present, classify SAM; if moderate criteria without edema, classify MAM.", "Assess danger signs: poor appetite, lethargy, seizures, hypoglycemia, hypothermia, dehydration/shock, infection, severe anemia, persistent vomiting, edema severity.", "Any serious complication, poor appetite, or generalized +++ edema → urgent facility/NRC assessment and stabilization.", "Clinically well, good appetite, no serious complication → supervised community nutritional programme with frequent reassessment.", "Escalate for deteriorating intake, weight loss, new edema, infection or failure of expected recovery."]}]}, {"title": "Algorithm 2 — complicated SAM: stabilization → transition → rehabilitation", "blocks": [{"t": "list", "ordered": true, "items": ["Stabilize: identify/treat hypoglycemia and hypothermia; treat infection; cautiously manage dehydration/electrolytes.", "Begin cautious starter diet (F-75); avoid high-sodium loads, rapid catch-up feeding and routine iron in early stabilization.", "Reassess appetite, edema, vital signs, urine, glucose and fluid-overload signs.", "Transition when clinically stable and appetite returns; gradually increase feeds toward F-100/catch-up diet.", "Rehabilitation: energy-dense feeds, protein, indicated iron and micronutrients, structured play and caregiver training.", "Discharge to CMAM follow-up when well, eating, edema resolved and growth improving; monitor relapse risk and social determinants."]}, {"t": "table", "head": ["<strong>Phase / parameter</strong>", "<strong>IAP 2026 Indian exam anchor</strong>", "<strong>Safety distinction</strong>"], "rows": [["F-75 starter", "~75 kcal/100 mL; ~0.9–1.1 g protein/100 mL", "Metabolically cautious; not for rapid catch-up"], ["Initial volume", "~130 mL/kg/day in 12 two-hourly feeds", "Gross edema: ~100 mL/kg/day example"], ["F-100 catch-up", "~100 kcal/100 mL; ~2.9 g protein/100 mL", "Transition after clinical stabilization"], ["Rehabilitation intake", "~150–180 kcal/kg/day; protein ~3.5–5.5 g/kg/day", "Target individualized to response and tolerance"], ["Iron", "Defer in stabilization; start in rehabilitation", "Do not mistake routine IFA prophylaxis for inpatient SAM therapy"], ["SAM symptomatic low glucose", "IAP example 10% dextrose 5 mL/kg IV; reassess 30 min", "Different from asymptomatic oral glucose pathway"], ["Transfusion assessment", "Hb &lt;6 g/dL with cardiopulmonary compromise or &lt;4 without (IAP SAM)", "Specialist-managed; avoid volume overload"]]}, {"t": "p", "html": "IAP 2026 specifically includes potassium supplementation (3–4 mEq/kg/day) for SAM children on locally prepared starter feeds, folic acid 5 mg day 1 then 1 mg/day for two weeks, zinc and vitamin A where indicated, and broad-spectrum antibiotics for inpatient complicated SAM. These are facility-protocol examples requiring clinical monitoring; do not apply them indiscriminately to all children or combine duplicate fortified supplements. [IAP-SAM]"}, {"t": "p", "html": "Complications: early hypoglycemia, hypothermia, infection, dehydration/shock, electrolyte derangements, cardiac failure and refeeding disturbances; late relapse, impaired linear growth, cognitive/developmental consequences and recurrent infection. IAP 2026 recovery criteria include WHZ &gt;−2 OR MUAC ≥12.5 cm, no edema for ≥2 weeks, good appetite and clinical wellness; continue follow-up and household food-security intervention. [IAP-SAM]"}]}, {"title": "A5. Vitamin A — ocular staging and Indian programme", "blocks": [{"t": "p", "html": "Vitamin A supports rod phototransduction, epithelial integrity and immunity. Deficiency may progress from night blindness (XN) → conjunctival xerosis (X1A) → Bitot spots (X1B) → corneal xerosis (X2) → corneal ulceration/keratomalacia (X3A &lt;1/3 cornea; X3B ≥1/3) → corneal scar (XS); xerophthalmic fundus (XF) is another feature. Corneal disease is urgent. Therapeutic dosing for xerophthalmia depends on age and presentation and is NOT the same as routine national prophylaxis."}, {"t": "p", "html": "NHM India: nine prophylactic doses from 9 months to 5 years. First at 9 months: 100,000 IU orally (often 1 mL if 100,000 IU/mL). Second at approximately 16–18 months: 200,000 IU; subsequent 200,000 IU doses at roughly six-month intervals up to five years. Verify the formulation and prior dose history. Do not routinely duplicate high-dose vitamin A in a child who recently received it without assessing indication. [NHM-VitA]"}]}, {"title": "A6. Vitamin D / calcium / phosphate — rickets differential", "blocks": [{"t": "p", "html": "Calcipenic rickets: low calcium availability from vitamin-D deficiency and/or low dietary calcium → secondary hyperparathyroidism → renal phosphate wasting and impaired growth-plate mineralization → wrist widening, rachitic rosary, genu varum/valgum and metaphyseal fraying/cupping. Calcium may remain normal because PTH compensates. Typical labs: raised ALP, often raised PTH, low/normal calcium, low phosphate, low 25-OH D if vitamin-D-deficient. Phosphopenic rickets (e.g. XLH): persistent hypophosphatemia with inappropriate renal phosphate wasting, often normal 25-OH D and no secondary PTH-driven explanation."}, {"t": "p", "html": "IAP revised 2021 vitamin D: &lt;12 ng/mL deficient; 12–20 insufficient; &gt;20 sufficient in its framework. Routine infancy 400 IU/day. Treatment of vitamin-D deficiency/rickets: oral cholecalciferol 2000 IU/day below one year; 3000 IU/day in older children, generally 12 weeks; ensure adequate calcium and follow clinical/biochemical response. Toxicity: 25-OH D &gt;100 ng/mL with hypercalcemia and/or hypercalciuria in IAP definition. These values are IAP-specific, not interchangeable with every international cutoff. [IAP-VitD]"}]}, {"title": "A7. Iron, folate and vitamin B12", "blocks": [{"t": "p", "html": "Iron deficiency: low iron intake / blood loss / malabsorption → impaired hemoglobin synthesis → microcytosis, hypochromia, high RDW and later pallor, irritability, pica or impaired cognition. Ferritin reflects iron stores but rises with inflammation; interpret with CRP, transferrin saturation, reticulocyte hemoglobin and clinical context. Thalassemia trait often has marked microcytosis with relatively high RBC count and normal RDW; Mentzer index MCV (fL)/RBC (million/µL) &lt;13 supports trait but is not diagnostic."}, {"t": "p", "html": "India AMB prophylaxis 6–59 months: 1 mL IFA syrup twice weekly, containing 20 mg elemental iron + 100 micrograms folic acid per mL. For ages 5–9 years: one weekly pink tablet with 45 mg elemental iron + 400 micrograms folate. For adolescents 10–19 years: weekly blue tablet 60 mg iron + 500 micrograms folate. Therapeutic iron for iron-deficiency anemia is different: many Indian algorithms use approximately 3 mg/kg/day elemental iron, adjusted to severity, product and response; check Hb response and adherence. [NHM-AMB]"}, {"t": "p", "html": "Vitamin B12 deficiency: low maternal stores, vegan/restrictive diet, malabsorption → impaired DNA synthesis and methylation → megaloblastic hematopoiesis, hypotonia, regression, movement disorder or neuropathy. Neurologic signs can precede obvious macrocytosis; combined iron and B12 deficiency may yield near-normal MCV. Folate can improve hematology while untreated B12 neurologic injury persists. Evaluate maternal/infant status and treat promptly using an age/etiology-appropriate specialist regimen. [IAP-Micro]"}]}, {"title": "A8. Zinc, iodine and less-common deficiency discriminators", "blocks": [{"t": "p", "html": "Indian NHM STOP Diarrhoea 2025: 2–&lt;6 months 10 mg elemental zinc daily for 14 days; 6 months–5 years 20 mg daily for 14 days; below two months not recommended in that programme. ORS remains primary dehydration treatment. WHO 2024/2025 international guideline conditionally suggests 5 mg daily for up to 14 days in children up to ten years, based on similar efficacy and less vomiting. This is a real SOURCE DIFFERENCE: do not silently replace the Indian national schedule with the WHO conditional dose. [NHM-Zinc, WHO-Diarrhoea]"}, {"t": "p", "html": "Iodine is needed for thyroid hormone and neurodevelopment. IAP 2026 cites iodized-salt targets ~30 ppm at production and ~15 ppm at consumer level. Iodized salt does not eliminate congenital thyroid dysgenesis; newborn screening remains essential. Zinc excess may cause copper deficiency (anemia, neutropenia, neurologic dysfunction). Thiamine deficiency causes beriberi/cardiac or neurologic disease; vitamin C deficiency causes scurvy with bleeding gums, bone pain and pseudoparalysis; folate deficiency causes megaloblastosis but usually not the classic B12 neurologic syndrome. [IAP-Micro]"}]}, {"title": "A9. Evidence strength and source-specific caveats", "blocks": [{"t": "table", "head": ["<strong>Established / strong clinical anchor</strong>", "<strong>Associated or context dependent</strong>", "<strong>Not established / avoid</strong>"], "rows": [["Breastfeeding, six-month complementary feeding, iron-rich diet", "Exact timing of preterm solids depends on readiness and local pathway", "Routine early solids at 4 months for every infant"], ["SAM diagnostic thresholds and edema criterion", "Specific therapeutic foods and antibiotic choices vary by programme", "Automatic high-volume boluses in all SAM"], ["Vitamin-D prophylaxis in infancy and treatment of rickets", "Testing/supplementation beyond infancy is risk dependent", "Universal high-dose vitamin D for all respiratory illnesses"], ["Vitamin-A prophylaxis programme in India", "Therapeutic dosing depends on ocular disease and age", "Weekly high-dose vitamin A as routine prevention"], ["Zinc plus ORS for childhood diarrhoea", "Indian NHM 10/20 mg vs WHO conditional 5 mg", "Claim that WHO and Indian doses are identical"]]}]}, {"title": "A10. Must-know numbers — source-tagged", "blocks": [{"t": "table", "head": ["<strong>Number</strong>", "<strong>Meaning / named framework</strong>"], "rows": [["6 months; ≥2 years", "Start complementary food at six completed months; continue breastfeeding ≥2 years (IAP 2026)"], ["MUAC &lt;115 / 115–&lt;125 / ≥125 mm", "SAM / MAM / above MUAC wasting band (6–59 mo, IAP 2026)"], ["WHZ &lt;−3 / −3 to &lt;−2", "SAM / MAM (IAP 2026)"], ["F-75 75 kcal/100 mL; 130 mL/kg/day", "Starter feed standard example (IAP 2026)"], ["100 mL/kg/day", "Gross-edema starter volume example (IAP 2026)"], ["F-100 100 kcal/100 mL; 150–180 kcal/kg/day", "Catch-up energy and rehabilitation target (IAP 2026)"], ["400 IU/day; 2000 IU/day; 3000 IU/day ×12 weeks", "Vitamin D infant prophylaxis; &lt;1 y treatment; older-child treatment (IAP revised 2021)"], ["100,000 IU at 9 mo; 200,000 IU subsequent", "India NHM vitamin-A programme, nine doses"], ["IFA 1 mL twice weekly = Fe 20 mg + folate 100 µg", "India AMB 6–59 months"], ["Zinc 10 mg 2–&lt;6 mo / 20 mg 6 mo–5 y ×14 d", "India NHM STOP Diarrhoea 2025"], ["Zinc 5 mg up to 14 d", "WHO 2024 conditional international guideline; differs from India"], ["Iodine 30 ppm factory / 15 ppm consumer", "IAP 2026 iodization target"]]}]}]}, {"id": "part-2", "title": "Supplementary High-Yield Topics — Integrated From Comparative Edition", "eyebrow": "", "group": "Study Notes", "kind": "notes", "sections": [{"title": "A11. Vitamin A therapy by age", "blocks": [{"t": "p", "html": "WHO xerophthalmia schedule. Treat the eye as an emergency (lubricant, protection, antibiotic for ulcers); treat the underlying malnutrition. Compare with NHM prophylaxis (A5) (source-specific verification required) Indian therapy wording."}]}, {"title": "A12. RUTF and community management", "blocks": [{"t": "p", "html": "RUTF is a lipid-based paste with very little free water: about 5.4 kcal/g, roughly 500 kcal per 92-g sachet (international specification (source-specific verification required) Indian CMAM product and band table). It is eaten without added water, is microbiologically safe at home and contains iron, so it is the main community-phase therapeutic food after a passed appetite test. The usual energy target is about 150–200 kcal/kg/day across RUTF and breast milk (programme-specific (source-specific verification required)). Give breast milk first, water alongside, and review weekly. F-75 and F-100 are water-based facility feeds, so do not use them at home."}]}, {"title": "A13. Kwashiorkor, marasmus and refeeding", "blocks": [{"t": "p", "html": "Refeeding syndrome: rapid energy loading drives phosphate, potassium and magnesium into cells → weakness, arrhythmia, cardiac failure, low serum phosphate. Prevention: cautious stepwise feeding, supplemented potassium and magnesium, early monitoring. Do not confuse with fluid overload (tachypnoea, crackles, hepatomegaly)."}]}, {"title": "A14. Rehydration in SAM", "blocks": [{"t": "p", "html": "Dehydration signs are unreliable in SAM and overload is easy, so rehydrate orally or by nasogastric tube when possible, slowly and with reassessment. WHO-style ReSoMal has about 45 mmol/L sodium and 40 mmol/L potassium (plus magnesium and trace minerals), i.e. less sodium and more potassium than standard ORS, because SAM has sodium excess and potassium depletion. Avoid IV fluids unless shock; use the protocol’s specified fluid and rate. Compositions and volumes vary between protocols (source-specific verification required) the Indian pathway. Stop fluids for new tachypnoea or crackles."}]}, {"title": "A15. Anaemia grading", "blocks": [{"t": "p", "html": "WHO 2011 cut-offs; name the age group in any severity question. SAM transfusion rules (A4) are separate."}]}, {"title": "A16. Scurvy, thiamine and other deficiencies", "blocks": [{"t": "p", "html": "Scurvy (vitamin C): infants on heated milk alone; irritability, “frog-leg” posture, pseudoparalysis from subperiosteal bleeding, bleeding swollen gums, scorbutic rosary; radiographs show ground-glass bones with a dense metaphyseal line and a Wimberger ring. Treat with vitamin C and dietary correction (dose per protocol (source-specific verification required)). Thiamine: infantile beriberi in infants of deficient mothers (cardiac failure, aphonia, neurological signs); also consider in refeeding and in TPN without vitamins. Copper: zinc excess or prolonged TPN. Iodine: see A8."}]}, {"title": "A17. Breastfeeding contraindications", "blocks": [{"t": "p", "html": "True indications to avoid breastfeeding: infant classic galactosaemia; a mother on cancer chemotherapy or receiving radioactive isotopes; HTLV-1 in settings with safe alternatives. Mastitis, hepatitis B with infant HBIG and vaccine, and HIV on effective ART (following national guidance) do not by themselves require stopping. Apply current NACO/IAP guidance (source-specific verification required)."}, {"t": "p", "html": "Clinical source caution: Specific SAM discharge rules, transfusion thresholds, fluid composition, and zinc age boundaries vary by publication and programme. Where a primary Indian circular has not been confirmed, this edition does not assert a universal Indian dose or decision rule. Use the named local protocol for bedside decisions."}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — apparent latch versus transfer", "blocks": [{"t": "p", "html": "A 35-week infant at day 5 has 10% weight loss, only 3 wet diapers/day, mild jaundice and persistent nipple clicking despite 20-minute feeds. BP/perfusion normal; breastfeeding observation shows shallow attachment and rare swallowing."}, {"t": "p", "html": "<strong>Question: </strong>What is the likely feeding problem and next step?"}, {"t": "p", "html": "<strong>Structured reasoning: </strong>Ineffective milk transfer in a late-preterm infant. Observe/correct attachment, evaluate hydration and bilirubin, quantify intake and provide expressed maternal milk if clinically indicated while protecting breastfeeding."}, {"t": "p", "html": "Closest distractor: normal cluster feeding; objective oliguria and weight loss exclude simple reassurance."}, {"t": "p", "html": "Trap: treating time attached to breast as a measure of transferred milk."}]}, {"title": "Case 2 — low-density diet", "blocks": [{"t": "p", "html": "A 9-month-old on breastfeeding and 4 bowls/day of watery rice gruel has slow weight gain, Hb 9.8 g/dL, no diarrhea and no edema. Development otherwise age appropriate."}, {"t": "p", "html": "<strong>Question: </strong>What should feeding counselling target first?"}, {"t": "p", "html": "<strong>Structured reasoning: </strong>Increase energy density and iron-rich diversity with thick spoonable food, pulses/egg/meat/fortified cereal and vitamin C; retain breastfeeding and responsive feeding."}, {"t": "p", "html": "Closest distractor: increase meal frequency alone; the frequency is already adequate but density and quality are not."}, {"t": "p", "html": "Trap: confusing number of bowls with nutrient adequacy."}]}, {"title": "Case 3 — discordant anthropometry", "blocks": [{"t": "p", "html": "A 21-month-old has MUAC 113 mm, WHZ −2.4, HAZ −2.1, no edema, good appetite, afebrile and alert."}, {"t": "p", "html": "<strong>Question: </strong>Classify and choose care setting."}, {"t": "p", "html": "<strong>Structured reasoning: </strong>SAM by MUAC &lt;115 mm; assess for complications and appetite. With no complications and good appetite, community-based rehabilitation with close follow-up is reasonable."}, {"t": "p", "html": "Closest distractor: MAM from WHZ alone; independent MUAC SAM criterion takes precedence."}, {"t": "p", "html": "Trap: averaging WHZ and MUAC into a less-severe label."}]}, {"title": "Case 4 — edema masks wasting", "blocks": [{"t": "p", "html": "A 27-month-old has bilateral foot edema ++, MUAC 128 mm, WHZ −1.4, RR 48/min and crackles with fever."}, {"t": "p", "html": "<strong>Question: </strong>What is the diagnosis and disposition?"}, {"t": "p", "html": "<strong>Structured reasoning: </strong>Edematous SAM with pneumonia/possible respiratory compromise; urgent inpatient evaluation and stabilization."}, {"t": "p", "html": "Closest distractor: normal nutritional status from MUAC; edema overrides weight-based reassurance."}, {"t": "p", "html": "Trap: focusing on MUAC instead of nutritional edema and danger signs."}]}, {"title": "Case 5 — SAM phase transition", "blocks": [{"t": "p", "html": "A 19-month-old (8 kg) admitted with complicated SAM received cautious F-75, antibiotics and electrolyte management. At 72 hours he is warm, alert, edema declining, appetite restored, and glucose stable."}, {"t": "p", "html": "<strong>Question: </strong>What nutritional transition is appropriate?"}, {"t": "p", "html": "<strong>Structured reasoning: </strong>Begin protocol-led transition toward F-100/catch-up feed, start indicated iron during rehabilitation, monitor edema/weight and teach caregivers."}, {"t": "p", "html": "Closest distractor: continuing F-75 forever; it is for stabilization, not catch-up."}, {"t": "p", "html": "Trap: starting iron during initial unstable phase or delaying transition despite recovery."}]}, {"title": "Case 6 — national programme conflict", "blocks": [{"t": "p", "html": "A 3-year-old with watery diarrhea has mild dehydration and no blood. ORS is available. One trainee quotes WHO 2024 zinc 5 mg/day; the unit follows NHM STOP Diarrhoea 2025."}, {"t": "p", "html": "<strong>Question: </strong>What is the correct source-specific approach?"}, {"t": "p", "html": "<strong>Structured reasoning: </strong>Use ORS for hydration and India NHM zinc 20 mg daily for 14 days; document that WHO 2024 conditionally suggests 5 mg internationally."}, {"t": "p", "html": "Closest distractor: declaring WHO and NHM identical; their published dose frameworks differ."}, {"t": "p", "html": "Trap: mixing sources without naming the recommendation."}]}, {"title": "Case 7 — regression with normal MCV", "blocks": [{"t": "p", "html": "An exclusively breastfed 10-month-old of a vegan mother has developmental regression, hypotonia, Hb 8.7 g/dL, MCV 80 fL and low ferritin."}, {"t": "p", "html": "<strong>Question: </strong>What important deficiency must not be missed?"}, {"t": "p", "html": "<strong>Structured reasoning: </strong>Vitamin B12 deficiency may coexist with iron deficiency; opposing cell-size changes can produce near-normal MCV. Urgent B12 assessment and treatment alongside iron evaluation."}, {"t": "p", "html": "Closest distractor: isolated iron deficiency; it does not explain the maternal risk and neuroregression."}, {"t": "p", "html": "Trap: ruling out B12 deficiency because MCV is not high."}]}, {"title": "Case 8 — phosphopenic versus calcipenic rickets", "blocks": [{"t": "p", "html": "A 4-year-old has genu varum, ALP 920 U/L, phosphate 2.1 mg/dL, normal 25-OH D, normal calcium, normal PTH and high fractional phosphate excretion."}, {"t": "p", "html": "<strong>Question: </strong>What mechanism and next evaluation?"}, {"t": "p", "html": "<strong>Structured reasoning: </strong>Renal phosphate wasting suggests phosphopenic rickets such as XLH; assess tubular phosphate handling, family history and specialist genetic/endocrine evaluation."}, {"t": "p", "html": "Closest distractor: nutritional vitamin-D deficiency; normal vitamin-D/PTH and inappropriate renal phosphate loss argue against it."}, {"t": "p", "html": "Trap: assuming every low-phosphate rickets is vitamin-D deficient."}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "Practice Station 1 — MUAC–WHZ discordance", "blocks": [{"t": "p", "html": "Question/data: Child A: MUAC 113 mm, WHZ −2.1, no oedema, appetite pass; Child B: MUAC 121 mm, WHZ −2.5, no oedema; Child C: MUAC 128 mm, WHZ −1.5 with bilateral nutritional oedema."}, {"t": "p", "html": "Interpretation: A is SAM by MUAC; B is MAM; C is oedematous SAM irrespective of anthropometry. Assess complications and appetite before deciding community versus facility care."}, {"t": "p", "html": "Closest distractor / discriminator: A single index, measurement, or ratio does not override the full clinical classification."}, {"t": "p", "html": "Trace-back: Nelson 22e nutrition concepts; WHO anthropometry and Indian programme implementation as explicitly applicable."}]}, {"title": "Practice Station 2 — Serial growth interpretation", "blocks": [{"t": "p", "html": "Question/data: HAZ at ages 6, 9, 12, 15, 18 months: −1.0, −1.8, −2.5, −3.0, −3.4; WHZ stays near −1.0."}, {"t": "p", "html": "Interpretation: Progressive severe linear growth faltering with relatively preserved weight-for-height. Normal WHZ does not exclude chronic malnutrition."}, {"t": "p", "html": "Closest distractor / discriminator: A single index, measurement, or ratio does not override the full clinical classification."}, {"t": "p", "html": "Trace-back: Nelson 22e nutrition concepts; WHO anthropometry and Indian programme implementation as explicitly applicable."}]}, {"title": "Practice Station 3 — Mentzer index", "blocks": [{"t": "p", "html": "Question/data: Child P: MCV 60 fL, RBC 5.9 million/µL, RDW 12%; child Q: MCV 66 fL, RBC 4.2 million/µL, RDW 18%."}, {"t": "p", "html": "Interpretation: P: 60/5.9 = 10.2, supporting thalassaemia trait; Q: 66/4.2 = 15.7, supporting iron deficiency. Neither ratio independently establishes diagnosis."}, {"t": "p", "html": "Closest distractor / discriminator: A single index, measurement, or ratio does not override the full clinical classification."}, {"t": "p", "html": "Trace-back: Nelson 22e nutrition concepts; WHO anthropometry and Indian programme implementation as explicitly applicable."}]}, {"title": "Practice Station 4 — Energy density", "blocks": [{"t": "p", "html": "Question/data: Illustrative foods: thin rice gruel 0.3 kcal/g, thick porridge 0.9 kcal/g, enriched porridge 1.3 kcal/g."}, {"t": "p", "html": "Interpretation: For a 100 g portion these yield 30, 90, and 130 kcal respectively; meal volume is not a substitute for energy density or dietary diversity."}, {"t": "p", "html": "Closest distractor / discriminator: A single index, measurement, or ratio does not override the full clinical classification."}, {"t": "p", "html": "Trace-back: Nelson 22e nutrition concepts; WHO anthropometry and Indian programme implementation as explicitly applicable."}]}, {"title": "Practice Station 5 — Recovery-criteria comparison", "blocks": [{"t": "p", "html": "Question/data: A child has WHZ −1.8, MUAC 123 mm, no oedema for three weeks, and good appetite."}, {"t": "p", "html": "Interpretation: Whether the child meets programme discharge criteria depends on whether the specified protocol requires both anthropometric criteria or permits one. Do not infer discharge from a single favourable measurement."}, {"t": "p", "html": "Closest distractor / discriminator: A single index, measurement, or ratio does not override the full clinical classification."}, {"t": "p", "html": "Trace-back: Nelson 22e nutrition concepts; WHO anthropometry and Indian programme implementation as explicitly applicable."}]}, {"title": "A12. Visual/data interpretation stations", "blocks": []}, {"title": "Visual Station 1 — MUAC screening threshold", "blocks": [{"t": "p", "html": "<strong>Question: </strong>A 22-month-old has MUAC 11.3 cm and WHZ −2.1. Interpret the MUAC band and explain disposition."}, {"t": "img", "src": "img/image1_q.png", "alt": ""}, {"t": "img", "src": "img/image1.png", "alt": "Grayscale MUAC screening thresholds: SAM below 11.5 cm, MAM 11.5 to below 12.5 cm, higher band at or above 12.5 cm.", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image, recording or validated diagnostic test."}, {"t": "p", "html": "<strong>Interpretation:</strong> SAM by MUAC &lt;11.5 cm; medical assessment and appetite determine care."}, {"t": "p", "html": "<strong>Decisive visual/data features:</strong> MUAC 11.3 cm lies left of the 11.5-cm boundary."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:</strong> WHZ −2.1 is MAM, but a different valid index can be more severe."}, {"t": "p", "html": "<strong>Next management step:</strong> Screen complications and appetite; refer if poor appetite or illness."}, {"t": "p", "html": "<strong>Exam trap:</strong> Do not average two different anthropometric criteria."}, {"t": "p", "html": "<strong>Trace-back:</strong> IAP 2026 SAM chapter; Day 14 A4."}]}, {"title": "Visual Station 2 — Serial growth trajectory", "blocks": [{"t": "p", "html": "<strong>Question: </strong>At 18 months, which abnormality is most severe in the plotted child and what does a near-normal WHZ mean?"}, {"t": "img", "src": "img/image2_q.png", "alt": ""}, {"t": "img", "src": "img/image2.png", "alt": "Serial growth chart: height-for-age z score falls below minus three while weight-for-height remains around minus one.", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image, recording or validated diagnostic test."}, {"t": "p", "html": "<strong>Interpretation:</strong> Progressive severe stunting with WHZ relatively preserved."}, {"t": "p", "html": "<strong>Decisive visual/data features:</strong> HAZ falls below −3 while WHZ stays around −1."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:</strong> A normal WHZ does not mean nutritional health when linear growth has deteriorated."}, {"t": "p", "html": "<strong>Next management step:</strong> Investigate prolonged dietary inadequacy, chronic illness and social determinants."}, {"t": "p", "html": "<strong>Exam trap:</strong> Do not use WHZ to rule out severe stunting."}, {"t": "p", "html": "<strong>Trace-back:</strong> IAP 2026 nutrition assessment; Day 13 growth + Day 14 A1."}]}, {"title": "Visual Station 3 — Microcytic versus macro-ovalocytic morphology", "blocks": [{"t": "p", "html": "<strong>Question: </strong>A child with anemia and neurologic regression has the right-hand morphology. Which deficiency should be assessed?"}, {"t": "img", "src": "img/image3_q.png", "alt": ""}, {"t": "img", "src": "img/image3.png", "alt": "Educational peripheral-smear schematic contrasting small pale microcytic cells with elongated macro-ovalocytes.", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image, recording or validated diagnostic test."}, {"t": "p", "html": "<strong>Interpretation:</strong> Macro-ovalocytic pattern supports megaloblastic processes including B12 deficiency."}, {"t": "p", "html": "<strong>Decisive visual/data features:</strong> Larger elongated RBC forms on right versus small pale cells on left."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:</strong> Microcytic iron deficiency can coexist and mask MCV; smear is suggestive, not definitive."}, {"t": "p", "html": "<strong>Next management step:</strong> Check B12/folate, diet, neurologic examination and iron indices."}, {"t": "p", "html": "<strong>Exam trap:</strong> Do not diagnose B12 solely from morphology without clinical/lab correlation."}, {"t": "p", "html": "<strong>Trace-back:</strong> Nelson conceptual hematology; IAP 2026 micronutrients; Day 14 A7."}]}, {"title": "Visual Station 4 — Complementary-food energy density", "blocks": [{"t": "p", "html": "<strong>Question: </strong>A 7-month-old gets three large bowls of very dilute rice gruel daily. Use the schematic to identify the main limitation."}, {"t": "img", "src": "img/image4.png", "alt": "Illustrative food energy-density bars contrasting watery gruel with thick enriched complementary foods."}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image, recording or validated diagnostic test."}, {"t": "p", "html": "<strong>Interpretation:</strong> Low energy density and low iron/protein diversity despite adequate apparent volume."}, {"t": "p", "html": "<strong>Decisive visual/data features:</strong> The dilute preparation has lower illustrative kcal/g than thick enriched foods."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:</strong> Increasing volume alone is limited by infant gastric capacity and satiety."}, {"t": "p", "html": "<strong>Next management step:</strong> Advise thick, energy-dense, iron-rich foods with continued breastfeeding."}, {"t": "p", "html": "<strong>Exam trap:</strong> Illustrative bars are not measured recipe composition or universal nutrient tables."}, {"t": "p", "html": "<strong>Trace-back:</strong> IAP 2026 infant nutrition; Day 14 A3."}]}, {"title": "Visual Station 5 — Indian versus WHO zinc decision data", "blocks": [{"t": "p", "html": "<strong>Question: </strong>For an NHM 2025 Indian programme case, a 4-month-old and a 30-month-old have diarrhoea. Select each dose and explain WHO difference."}, {"t": "table", "head": ["<strong>Age</strong>", "<strong>India NHM 2025</strong>", "<strong>WHO 2024 conditional comparison</strong>"], "rows": [["4 months", "10 mg/day ×14 days", "5 mg/day up to 14 days"], ["30 months", "20 mg/day ×14 days", "5 mg/day up to 14 days"]]}, {"t": "p", "html": "<strong>Interpretation:</strong> India NHM 2025: 4 months 10 mg/day, 30 months 20 mg/day, both ×14 days; WHO 2024 conditionally suggests 5 mg/day internationally."}, {"t": "p", "html": "<strong>Decisive visual/data features:</strong> Age band crosses six months in Indian programme; source date matters."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:</strong> WHO 2024 is not a claim that NHM 2025 was replaced."}, {"t": "p", "html": "<strong>Next management step:</strong> Use ORS and Indian age-specific zinc; document international comparison if needed."}, {"t": "p", "html": "<strong>Exam trap:</strong> Do not merge guidelines or give both zinc doses."}, {"t": "p", "html": "<strong>Trace-back:</strong> NHM STOP Diarrhoea 2025; WHO diarrhoea guideline 2024; Day 14 A8."}]}]}, {"id": "revision", "title": "Rapid Revision", "group": "Practice", "kind": "revision", "sections": [{"title": "", "blocks": [{"t": "p", "html": "<strong>Diagnosis:</strong> SAM 6–59 mo = WHZ &lt;−3 OR MUAC &lt;115 mm OR bilateral nutritional edema. MAM = WHZ −3 to &lt;−2 OR MUAC 115–&lt;125 mm, without edema. HAZ &lt;−3 = severe stunting; WAZ alone cannot diagnose SAM."}, {"t": "p", "html": "<strong>Disposition:</strong> Complicated SAM, poor appetite or +++ edema → facility. Uncomplicated good-appetite SAM/MAM → community with frequent monitoring. Appetite-test pass ≥¾ offered weight-banded test feed in Indian CMAM protocol."}, {"t": "p", "html": "<strong>Phase sequence:</strong> Stabilize glucose, temperature, infection, fluids/electrolytes → F-75 ~75 kcal/100 mL; 130 mL/kg/day, gross edema 100 mL/kg/day → appetite returns → F-100/catch-up → iron in rehabilitation → discharge with CMAM follow-up."}, {"t": "p", "html": "<strong>Recovery:</strong> IAP 2026: WHZ &gt;−2 OR MUAC ≥12.5 cm plus no edema ≥2 weeks, clinically well, good appetite; prevent relapse."}, {"t": "p", "html": "<strong>Feeding:</strong> Breastfeeding within 1 h; exclusive 6 completed months; complementary thick diverse iron-rich food from 6 months; continue breastfeeding ≥2 y. Late preterm: verify actual milk transfer."}, {"t": "p", "html": "<strong>Vitamin A:</strong> NHM 9 doses: first 100,000 IU at 9 mo, subsequent 200,000 IU to 5 y. Night blindness → xerosis/Bitot → corneal disease: urgent therapeutic care."}, {"t": "p", "html": "<strong>Vitamin D:</strong> IAP 2021: infant prevention 400 IU/day; treatment &lt;1 y 2000 IU/day ×12 wk, older child 3000 IU/day ×12 wk. 25-OH D &lt;12 deficient; 12–20 insufficient; &gt;20 sufficient."}, {"t": "p", "html": "<strong>Iron/B12:</strong> AMB 6–59 mo 1 mL IFA twice weekly = Fe 20 mg + folate 100 µg. Therapy often ~3 mg/kg/day elemental iron. High RBC/low Mentzer suggests thal trait; regression in vegan infant → B12 even if MCV normal."}, {"t": "p", "html": "<strong>Zinc/Iodine:</strong> NHM 2025 zinc 10 mg 2–&lt;6 mo / 20 mg ≥6 mo to 5 y ×14 d. WHO 2024 conditional 5 mg/day is DIFFERENT. Iodized salt 30 ppm factory, 15 ppm consumer."}, {"t": "p", "html": "<strong>Exam traps:</strong> Edema overrides WHZ; WAZ ≠ SAM; F-75 ≠ F-100; no early iron in unstable SAM; infant vitamin-D prevention ≠ treatment; vitamin-A prophylaxis ≠ xerophthalmia therapy; ORS ≠ zinc; Indian ≠ WHO zinc dose."}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": true, "items": ["State the three independent SAM criteria in 6–59-month children.<br>Answer: WHZ &lt;−3, MUAC &lt;115 mm, or bilateral nutritional pitting edema.", "Give MAM WHZ and MUAC bands.<br>Answer: WHZ −3 to &lt;−2; MUAC 115 to &lt;125 mm, with no nutritional edema.", "Which index detects stunting and which wasting?<br>Answer: HAZ detects stunting; WHZ/WFL detects wasting.", "State the Indian 2023 CMAM appetite-test pass rule.<br>Answer: At least three-quarters of the weight-banded test feed consumed within up to one hour, with clinical observation.", "What mandates inpatient care despite good appetite in WHO 2023 SAM guidance?<br>Answer: Generalized +++ nutritional edema.", "List the first five priorities in complicated SAM.<br>Answer: Recognize/treat hypoglycemia, hypothermia, dehydration/shock carefully, electrolyte problems and infection, while beginning cautious starter feeding.", "Give F-75 and F-100 kcal per 100 mL.<br>Answer: F-75 ≈75 kcal/100 mL; F-100 ≈100 kcal/100 mL.", "Give IAP 2026 starter-feed volume and gross-edema exception.<br>Answer: 130 mL/kg/day commonly in 12 feeds; gross edema example 100 mL/kg/day.", "When is iron introduced in complicated SAM?<br>Answer: During rehabilitation after stabilization, not routine early stabilization.", "Give IAP 2026 rehabilitation energy and protein anchors.<br>Answer: About 150–180 kcal/kg/day and 3.5–5.5 g protein/kg/day.", "State India NHM first and subsequent vitamin-A prophylaxis doses.<br>Answer: 100,000 IU at 9 months; 200,000 IU at subsequent scheduled doses to 5 years, nine doses total.", "Name the progression from night blindness to corneal involvement.<br>Answer: Night blindness → conjunctival xerosis/Bitot spots → corneal xerosis → ulceration/keratomalacia → scarring.", "Give IAP infant vitamin-D prophylaxis and infant treatment dose.<br>Answer: 400 IU/day prophylaxis; 2000 IU/day for 12 weeks to treat deficiency/rickets below one year.", "Give IAP older-child rickets treatment dose and duration.<br>Answer: Cholecalciferol 3000 IU/day for 12 weeks, plus calcium adequacy and follow-up.", "Give IAP 25-OH vitamin-D deficiency/insufficiency/sufficiency cutoffs.<br>Answer: &lt;12 ng/mL deficient; 12–20 insufficient; &gt;20 sufficient in the IAP framework.", "Give AMB prophylactic IFA syrup dose and composition for 6–59 months.<br>Answer: 1 mL twice weekly; 20 mg elemental iron +100 µg folic acid per mL.", "How does therapeutic iron differ from AMB prophylaxis?<br>Answer: Therapy for iron-deficiency anemia is weight-based (commonly ~3 mg/kg/day elemental iron in Indian algorithms), not the fixed twice-weekly preventive regimen.", "State two discriminators of thalassemia trait versus iron deficiency.<br>Answer: Trait: relatively high RBC count and often normal RDW; iron deficiency: often high RDW and response to iron.", "Why can B12 deficiency have normal MCV?<br>Answer: Coexisting microcytic iron deficiency can mask macrocytosis.", "What laboratory pattern suggests phosphopenic renal rickets?<br>Answer: Low phosphate with inappropriate renal phosphate wasting, often normal 25-OH D and no secondary PTH cause.", "State Indian NHM 2025 zinc doses by age and WHO 2024 difference.<br>Answer: India: 2–&lt;6 mo 10 mg/day and 6 mo–5 y 20 mg/day ×14 days; WHO 2024 conditionally suggests 5 mg/day up to 14 days.", "What are iodized-salt targets at factory and consumer level?<br>Answer: Approximately 30 ppm at production and 15 ppm at household/consumer level in IAP 2026.", "Visual pattern: MUAC 11.2 cm but WHZ −2.1. What classification?<br>Answer: SAM because MUAC &lt;115 mm independently qualifies.", "Visual pattern: HAZ −3.3, WHZ −0.5. What does this mean?<br>Answer: Severe stunting without current wasting.", "Visual pattern: macro-ovalocytes plus infant regression in vegan maternal context. What test/management priority?<br>Answer: Urgent infant and maternal B12 assessment and indicated treatment; assess iron/folate co-deficiency."]}]}]}, {"id": "notebook", "title": "Error Notebook", "group": "Revise", "kind": "notebook", "sections": []}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "Self-Assessment, Error Notebook & Spaced Review", "h1": "Self-Assessment, Error Notebook & Spaced Review", "blocks": [{"t": "p", "html": "Base MCQs: ___ / 75 correct; Notebook Retests — Extra: ___ / 6 correct; Calculation Drill: ___ / 8 correct; Active Recall: ___ / 25 mastered. Track time and confidence separately."}, {"t": "p", "html": "RAG: GREEN = correct with clear reasoning and can explain closest distractor; AMBER = correct but guessed/slow/uncertain; RED = wrong or unable to explain discriminator. All AMBER and RED concepts enter the error notebook with K/C/R/G/S tag."}, {"t": "p", "html": "R1: ~24 h fresh active recall; R2: ~7 days fresh application; R3: ~21 days retention. A correct retest changes status to Improving, not automatically Mastered. If failed again, increment ×2, ×3 etc. Retest source IDs are disclosed only in Section C after answering."}, {"t": "p", "html": "Due/overdue active notebook concepts represented here: ERR-D5-Q34 (DOPE equipment), ERR-D6-Q60 (G6PD jaundice), ERR-D10-Q8 (PES vs CPS time), ERR-D10-Q15 (neonatal ECF diuresis), ERR-D10-Q47 (GIR conversion), ERR-D10-Q50 (hyperinsulinism). Unresolved concepts such as Day 5 Q4 and the reported Day 10 Q65 are NOT fabricated into retests."}, {"t": "p", "html": "Follow-up review windows: D5-Q53 Jensen BPD and D7-Q34 EEG seizure due around 13 Oct; D8-Q41 preterm energy/protein due around 14 Oct. Confirm status in notebook before re-testing to avoid duplicate already-mastered items."}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "Primary Source Map & Verification (Accessed 12 October 2026)", "h1": "Primary Source Map & Verification (Accessed 12 October 2026)", "blocks": [{"t": "p", "html": "[Nelson 22e] Nelson Textbook of Pediatrics, 22nd Edition — primary conceptual textbook; source chapter text is not reproduced."}, {"t": "p", "html": "[IAP-Infant] IAP Presidential Action Plan 2026: Infant Nutrition (Exclusive Breastfeeding, Complementary Feeding, Growth Monitoring). https://iapindia.org/pdf/action-plan-2026/Nutrition/006-Infant-Nutrition-Exclusive-Breastfeeding-Complementary-Feeding-Growth-Monitoring.pdf"}, {"t": "p", "html": "[IAP-SAM] IAP Presidential Action Plan 2026: Malnutrition — MAM &amp; SAM. https://iapindia.org/pdf/action-plan-2026/Nutrition/008-Malnutrition-MAM-Moderate-Acute-Malnutrition-and-SAM-Severe-Acute-Malnutrition.pdf"}, {"t": "p", "html": "[IAP-Assessment] IAP Presidential Action Plan 2026: Assessment of Nutrition in Children. https://iapindia.org/pdf/action-plan-2026/Nutrition/002-Assessment-of-Nutrition-in-Children.pdf"}, {"t": "p", "html": "[IAP-Micro] IAP Presidential Action Plan 2026: Paediatric Micronutrients Beyond the Big Five. https://iapindia.org/pdf/action-plan-2026/Nutrition/004-Paediatric-Micronutrients-of-Public%20Health-Importance-Beyond-the-Big-Five.pdf"}, {"t": "p", "html": "[IAP-VitD] IAP Revised (2021) Guidelines on Vitamin D Deficiency and Rickets (Indian Pediatrics 2022). https://pubmed.ncbi.nlm.nih.gov/34969941/"}, {"t": "p", "html": "[IAP-U6M] IAP/PANS 2025: Prevention and Management of Growth Failure in the First Six Months. https://pubmed.ncbi.nlm.nih.gov/40214941/"}, {"t": "p", "html": "[MoWCD-CMAM] Government of India 2023 Protocol for Management of Malnutrition in Children, MoWCD/MoHFW. https://wcd.gov.in/pregnant-lactating-women-children/nutrition-mission-saksham-anganwadi-and-poshan-2-0-portals-protocol-for-management-of-malnutrition-in-children"}, {"t": "p", "html": "[NHM-VitA] National Health Mission: Vitamin A supplementation. https://nhm.gov.in/index1.php?lang=1&amp;level=3&amp;sublinkid=1452&amp;lid=801"}, {"t": "p", "html": "[NHM-AMB] National Health Mission: Anemia Mukt Bharat operational guidelines. https://nhm.gov.in/images/pdf/Nutrition/AMB-guidelines/Anemia-Mukt-Bharat-Operational-Guidelines-FINAL.pdf"}, {"t": "p", "html": "[NHM-Zinc] NHM STOP Diarrhoea Campaign 2025 guidance (India age-specific zinc doses). https://nhm.gov.in/New_Updates_2018/NHM_Components/RMNCHA/CH/Schemes/IDCF/IDCF-2025/Guidance_Document_on-STOP_Diarrhoea_Campaign_2025.pdf"}, {"t": "p", "html": "[WHO-Wasting] WHO 2023 Guideline on Prevention and Management of Wasting and Nutritional Oedema. https://www.who.int/publications/i/item/9789240082830"}, {"t": "p", "html": "[WHO-Diarrhoea] WHO 2024/2025 Guideline on Management of Pneumonia and Diarrhoea in Children up to 10 Years (conditional 5-mg zinc). https://www.who.int/publications/i/item/9789240103412"}, {"t": "p", "html": "[NIN-2024] ICMR-NIN Dietary Guidelines for Indians 2024. https://www.nin.res.in/dietaryguidelines/pdfjs/locale/DGI07052024P.pdf"}, {"t": "p", "html": "Clinical caveat: IAP 2026 practice chapters may cite older studies or institutional approaches. Recommendations requiring local implementation (therapeutic feed recipe, antibiotic selection, rehydration solutions, discharge thresholds) should be applied using the current institutional/national pathway. Exam answers identify the named framework. No AAP protocol is used as the default."}]}, {"title": "Comparative Editorial Summary", "h1": "Comparative Editorial Summary", "blocks": [{"t": "p", "html": "Original standalone: 75 base MCQs + 6 interleaved notebook retests, 5 visual stations, 8 calculation drills, detailed Section C and separate Active Recall answers."}, {"t": "p", "html": "Attached V4: 89 questions (75 base + 6 notebook retests + 8 extra gap-fill items), 6 quantitative data stations and 10 calculation drills; adds seven important nutrition and SAM subtopics."}, {"t": "p", "html": "Consolidation decision: preserve the locked scored-question architecture; add the seven complementary teaching topics and five unscored quantitative interpretation exercises. Do not silently introduce eight additional gap-fill questions into the base count."}, {"t": "p", "html": "Verification limitation: The attached V4 itself identifies unresolved source-specific recommendations. This consolidation does not constitute independent primary-source verification of every protocol claim or full medical QA of all MCQs."}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 17, "n": 17}, {"k": 2, "from": 18, "to": 33, "n": 16}, {"k": 3, "from": 34, "to": 49, "n": 16}, {"k": 4, "from": 50, "to": 65, "n": 16}, {"k": 5, "from": 66, "to": 81, "n": 16}], "mcqCount": 81, "calc": {"n": 8, "href": "calc.html"}};
